// Typed access to src/content/pages.json (generated by scripts/extract-copy.py from docs/11-PAGES). Never retype this copy.
import raw from './pages.json';
import type { Lang } from '../i18n/routes';

export interface Cell { eyebrow: string; title: string; body: string; items: string[]; button: string | null }
export interface SectionData { n: number; type: string; vi: Cell; en: Cell; imagesNote: string; effects: string[] }
export interface PageData { vi: string; en: string; tier: 'S' | 'A' | 'B'; sections: SectionData[] }
export const pages = raw as unknown as Record<string, PageData>;

export const getPage = (pid: string): PageData => {
  const p = pages[pid];
  if (!p) throw new Error(`pages.json: unknown page ${pid}`);
  return p;
};
export const cellOf = (s: SectionData, lang: Lang): Cell => s[lang];

/** Items end with an artefact period on the last entry only; remove it from list items. */
export const clean = (s: string): string => s.replace(/\.$/, '').trim();
/** Sentences (FAQ answers) always end with a period. */
export const sentence = (s: string): string => (/[.!?]$/.test(s.trim()) ? s.trim() : s.trim() + '.');
/** Split "a, b, rest..." into the first n comma parts and the remainder. */
export function splitN(s: string, n: number): string[] {
  const out: string[] = []; let rest = s;
  for (let i = 0; i < n; i++) { const k = rest.indexOf(', '); if (k < 0) break; out.push(rest.slice(0, k)); rest = rest.slice(k + 2); }
  out.push(rest);
  return out;
}
